<?php require_once __DIR__.'/../../includes/bootstrap.php';require_role('petugas');require_once __DIR__.'/../../includes/document_tools.php';$pid=(int)($_GET['petugas_id']??0);require_selected_petugas($pid);$id=(int)($_GET['progress_id']??0);$q=$pdo->prepare("SELECT ph.id_progress,ph.id_petugas,ph.id_kegiatan,p.id_user,k.tujuan_akhir FROM progress_harian ph JOIN petugas p ON p.id_petugas=ph.id_petugas JOIN kegiatan k ON k.id_kegiatan=ph.id_kegiatan WHERE ph.id_progress=? AND ph.id_petugas=?");$q->execute([$id,$pid]);$r=$q->fetch();if(!$r||(int)$r['id_user']!==(int)current_user()['id_user']){http_response_code(403);exit('Akses ditolak.');}if(!in_array($r['tujuan_akhir'],['lpd','keduanya'],true)){http_response_code(403);exit('LPD tidak tersedia untuk kegiatan ini.');}try{$pdf=sipacak_progress_pdf($pdo,$id);sipacak_download_pdf($pdf,'LPD_'.$pid.'_'.$id.'.pdf');}catch(Throwable $e){http_response_code(422);exit(e($e->getMessage()));}
